shipments.MapGet("", async (IShipmentService service) =>
    Results.Ok(await service.GetAllShipmentsAsync()));

shipments.MapGet("track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
{
    var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
    return shipment is null ? Results.NotFound() : Results.Ok(shipment);
});

shipments.MapPost("", async (ShipmentDto dto, IShipmentService service) =>
{
    var created = await service.CreateShipmentAsync(dto);
    return Results.Created($"api/shipments/track/{created.TrackingNumber}", created);
});

shipments.MapPut("{id}/status", async (int id, StatusUpdateRequest request, IShipmentService service) =>
{
    var updated = await service.UpdateShipmentStatusAsync(id, request.Status);
    return Results.Ok(updated);
});
```

Also add this record at the bottom of Program.cs (or in a separate file):
```csharp
public record StatusUpdateRequest(ShipmentStatus Status);
```

Add the `using ShipmentTracker.Client;` and `using ShipmentTracker.Services;` to Program.cs.

Register the service in server `Program.cs`:
```csharp
builder.Services.AddScoped<IShipmentService, ShipmentServerService>();
```

### 7. Client Program.cs — Register HttpClient and service

Update client `Program.cs` to register HttpClient and the client service:
```csharp
builder.Services.AddScoped(sp =>
    new HttpClient { BaseAddress = new Uri(builder.HostEnvironment.BaseAddress) });
builder.Services.AddScoped<IShipmentService, ShipmentHttpService>();
```

### 8. Pages — Client project (`ShipmentTracker.Client/Pages/`)

**Remove** the template pages: `Counter.razor`, `Weather.razor`, `Auth.razor`. Keep `Home.razor` and `NotFound.razor`.

**Replace `Home.razor`** with a landing/dashboard page:
```razor
@page "/"

